on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  mega_shine_cards integer;
  mega_shine_packs integer;
  mega_shine_odds integer;
begin
  select count(*)
  into mega_shine_cards
  from public.cards
  where set_id = 'B2b';

  select count(*)
  into mega_shine_packs
  from public.packs
  where set_id = 'B2b';

  select count(*)
  into mega_shine_odds
  from public.card_pack_odds
  where pack_id = 'b2b-mega-shine';

  if mega_shine_cards <> 117 then
    raise exception
      'Expected 117 Mega Shine cards, found %',
      mega_shine_cards;
  end if;

  if mega_shine_packs <> 1 then
    raise exception
      'Expected 1 Mega Shine pack, found %',
      mega_shine_packs;
  end if;

  if mega_shine_odds <> 117 then
    raise exception
      'Expected 117 Mega Shine odds rows, found %',
      mega_shine_odds;
  end if;
end
$$;

commit;

-- Expected: 117 total records for the Mega Shine pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b2b-mega-shine'
group by cards.rarity
order by min(cards.collector_number);
